1	/**
2	 * @module features/tv-dashboard/ui/TvStoreCard
3	 *
4	 * Card de loja do Painel TV (602×280 — design.md §4): vendas do dia (ou
5	 * defasadas com selo honesto), barra de % meta, mini-stats e borda RAG
6	 * com redundância não-cromática (glow + chip de estado).
7	 */
8	
9	import { ArrowDownRight, ArrowUpRight } from 'lucide-react';
10	import type { TvFreshnessLevel, TvStoreData } from '../model/types';
11	import { formatCompactBRL, parseBrDateTime, parseIsoDateLocal } from '../model/tvMath';
12	import {
13	  TvDeltaChip,
14	  TvMetaBar,
15	  TvSourceChip,
16	  TvStateChip,
17	  TvStockBadge,
18	} from './TvChips';
19	import {
20	  WEEKDAY_ABBR,
21	  expectedPctNow,
22	  formatInt,
23	  formatTicketBRL,
24	  formatTimeHHMM,
25	  formatWeekdayDayMonth,
26	  metaBarColorFromRatio,
27	} from './tvFormat';
28	import { useCountUp } from './useCountUp';
29	
30	interface TvStoreCardProps {
31	  store: TvStoreData;
32	  /** Freshness consolidado da fonte de vendas live (chip "ao vivo"/"atrasado"). */
33	  liveLevel: TvFreshnessLevel;
34	  now: Date;
35	}
36	
37	/** Borda + glow por estado RAG (design.md §4 — sinal lível a 5m). */
38	const RAG_FRAME: Record<TvStoreData['rag'], { cls: string; shadow?: string }> = {
39	  ok: { cls: 'border border-tv-border' },
40	  amber: {
41	    cls: 'border-2 border-tv-amber',
42	    shadow: '0 0 0 1px #F5A623, 0 0 28px -8px rgba(245,166,35,0.45)',
43	  },
44	  red: {
45	    cls: 'border-2 border-tv-red',
46	    shadow: '0 0 0 1px #E5484D, 0 0 32px -8px rgba(229,72,77,0.55)',
47	  },
48	};
49	
50	/** Card de loja: cobre canal Degust live e Linx defasado. */
51	export function TvStoreCard({ store, liveLevel, now }: TvStoreCardProps) {
52	  const { vendas, metaDia, channel } = store;
53	  const isLive = channel === 'degust-live';
54	  const valorAnim = useCountUp(vendas?.valor ?? 0);
55	  const cuponsAnim = Math.round(useCountUp(vendas?.cupons ?? 0));
56	  const frame = RAG_FRAME[store.rag];
57	
58	  // Barra: preenchimento = % do dia COMPLETO; tick pró-rata só no canal live
59	  const fullDayPct =
60	    vendas != null && metaDia != null && metaDia > 0
61	      ? (vendas.valor / metaDia) * 100
62	      : null;
63	  const expected = isLive ? expectedPctNow(now) : null;
64	  const barColor = isLive
65	    ? metaBarColorFromRatio(store.pctMeta != null ? store.pctMeta / 100 : null, now)
66	    : 'sage';
67	
68	  const bipTime = formatTimeHHMM(store.movimentacao.ultimaBipagem);
69	  const refDate = vendas ? parseIsoDateLocal(vendas.dataReferencia) : null;
70	
71	  // Caption sob as vendas (design.md §4 item 4)
72	  let caption: string;
73	  if (vendas == null) {
74	    caption = 'sem dado de venda disponível';
75	  } else if (isLive) {
76	    // `ultima_atualizacao` do Degust vem "DD/MM/YYYY HH:mm:ss" — parser
77	    // dedicado pt-BR (new Date() falha para dia > 12).
78	    const upd = formatTimeHHMM(parseBrDateTime(vendas.atualizadoEm));
79	    caption = `hoje${upd ? ` · atualizado ${upd}` : ''}${bipTime ? ` · bip ${bipTime}` : ''}`;
80	  } else {
81	    caption = `${refDate ? formatWeekdayDayMonth(refDate) : ''} — último dia com dados${bipTime ? ` · bip ${bipTime}` : ''}`;
82	  }
83	
84	  return (
85	    <section
86	      className={`flex flex-col rounded-2xl bg-tv-surface p-5 transition-[border-color,box-shadow] [transition-duration:400ms] motion-reduce:transition-none ${frame.cls}`}
87	      style={frame.shadow ? { boxShadow: frame.shadow } : undefined}
88	      data-testid="tv-store-card"
89	      data-rag={store.rag}
90	    >
91	      {/* Header: nome + chips */}
92	      <div className="flex h-8 items-center justify-between gap-3">
93	        <h2 className="truncate text-[28px] font-momma font-semibold leading-8 text-tv-text">
94	          {store.nome}
95	        </h2>
96	        <div className="flex shrink-0 items-center gap-2">
97	          <TvStateChip rag={store.rag} />
98	          <TvStockBadge estoque={store.estoque} />
99	          <TvSourceChip
100	            channel={channel}
101	            liveLevel={liveLevel}
102	            laggedDate={vendas?.dataReferencia ?? null}
103	          />
104	        </div>
105	      </div>
106	
107	      {/* Vendas (64px) + delta */}
108	      <div className="mt-1.5 flex items-end gap-4">
109	        <span
110	          className={`font-tv-num text-[64px] font-bold leading-none tabular-nums ${vendas ? 'text-tv-text' : 'text-tv-dim'}`}
111	          data-testid="tv-store-sales"
112	        >
113	          {vendas ? formatCompactBRL(valorAnim) : '—'}
114	        </span>
115	        {store.deltaSemana != null && refDate != null && (
116	          <span className="pb-1">
117	            <TvDeltaChip
118	              delta={store.deltaSemana}
119	              weekdayLabel={WEEKDAY_ABBR[refDate.getDay()]}
120	              size="card"
121	            />
122	          </span>
123	        )}
124	      </div>
125	      <p className="mt-1 text-[20px] font-momma font-medium leading-tight text-tv-dim">
126	        {caption}
127	      </p>
128	
129	      {/* Barra de meta */}
130	      <div className="mt-2">
131	        <TvMetaBar
132	          fillPct={fullDayPct}
133	          expectedPct={fullDayPct != null ? expected : null}
134	          color={barColor}
135	          size="card"
136	        />
137	        <p className="mt-1.5 text-[22px] font-momma leading-tight">
138	          {fullDayPct != null ? (
139	            isLive ? (
140	              <>
141	                <span className="font-medium text-tv-mut">
142	                  {Math.round(fullDayPct)}% da meta
143	                </span>
144	                <span className="text-tv-dim"> · esperado {expected}%</span>
145	              </>
146	            ) : (
147	              <span className="font-medium text-tv-mut">
148	                {Math.round(fullDayPct)}% da meta de{' '}
149	                {refDate ? WEEKDAY_ABBR[refDate.getDay()] : '—'}
150	              </span>
151	            )
152	          ) : (
153	            <span className="text-tv-dim">sem meta cadastrada</span>
154	          )}
155	        </p>
156	      </div>
157	
158	      {/* Mini-stats */}
159	      <div className="mt-auto grid grid-cols-3 gap-4">
160	        <div>
161	          <p className="text-[22px] font-momma font-medium uppercase tracking-[0.08em] text-tv-mut">
162	            CUPONS
163	          </p>
164	          <p className="mt-0.5 font-tv-num text-[32px] font-medium leading-none text-tv-text tabular-nums">
165	            {vendas?.cupons != null ? formatInt(cuponsAnim) : '—'}
166	          </p>
167	        </div>
168	        <div>
169	          <p className="text-[22px] font-momma font-medium uppercase tracking-[0.08em] text-tv-mut">
170	            TICKET
171	          </p>
172	          <p className="mt-0.5 font-tv-num text-[32px] font-medium leading-none text-tv-text tabular-nums">
173	            {vendas?.ticketMedio != null ? formatTicketBRL(vendas.ticketMedio) : '—'}
174	          </p>
175	        </div>
176	        <div>
177	          <p className="text-[22px] font-momma font-medium uppercase tracking-[0.08em] text-tv-mut">
178	            FLUXO
179	          </p>
180	          <p className="mt-0.5 flex items-center gap-1 font-tv-num text-[28px] font-medium leading-none text-tv-text tabular-nums">
181	            <ArrowUpRight style={{ width: 22, height: 22 }} className="text-tv-mut" aria-hidden />
182	            {store.movimentacao.entradas}
183	            <ArrowDownRight
184	              style={{ width: 22, height: 22 }}
185	              className="ml-2 text-tv-mut"
186	              aria-hidden
187	            />
188	            {store.movimentacao.saidas}
189	          </p>
190	        </div>
191	      </div>
192	    </section>
193	  );
194	}
