1	/**
2	 * @module features/tv-dashboard/ui/TvFabricaCard
3	 *
4	 * Card diferenciado da fábrica (602×280, posição 6 — design.md §5):
5	 * produção do dia (com data de referência explícita quando fallback),
6	 * expedições, última bipagem e hairline gold de identidade.
7	 */
8	
9	import { Factory } from 'lucide-react';
10	import type { TvFactoryData, TvFreshness } from '../model/types';
11	import {
12	  FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
13	  TV_FACTORY_HOURS,
14	  parseIsoDateLocal,
15	  toIsoDateLocal,
16	} from '../model/tvMath';
17	import { TvSourceChip, TvStateChip, TvStockBadge } from './TvChips';
18	import {
19	  formatAgoLabel,
20	  formatInt,
21	  formatTimeHHMM,
22	  formatWeekdayDayMonth,
23	} from './tvFormat';
24	import { useCountUp } from './useCountUp';
25	
26	interface TvFabricaCardProps {
27	  factory: TvFactoryData;
28	  freshness: TvFreshness;
29	  now: Date;
30	}
31	
32	/** Borda + glow por estado RAG (mesmo chassi do TvStoreCard). */
33	const RAG_FRAME: Record<TvFactoryData['rag'], { cls: string; shadow?: string }> = {
34	  ok: { cls: 'border border-tv-border' },
35	  amber: {
36	    cls: 'border-2 border-tv-amber',
37	    shadow: '0 0 0 1px #F5A623, 0 0 28px -8px rgba(245,166,35,0.45)',
38	  },
39	  red: {
40	    cls: 'border-2 border-tv-red',
41	    shadow: '0 0 0 1px #E5484D, 0 0 32px -8px rgba(229,72,77,0.55)',
42	  },
43	};
44	
45	/** Card da fábrica: nunca tem meta de venda — só produção/expedição/bip. */
46	export function TvFabricaCard({ factory, freshness, now }: TvFabricaCardProps) {
47	  const producao = factory.producao;
48	  const unidadesAnim = Math.round(useCountUp(producao?.totalUnidades ?? 0));
49	  const frame = RAG_FRAME[factory.rag];
50	
51	  const todayIso = toIsoDateLocal(now);
52	  const isToday = producao?.dataReferencia === todayIso;
53	  const refLabel =
54	    producao && !isToday
55	      ? formatWeekdayDayMonth(parseIsoDateLocal(producao.dataReferencia))
56	      : null;
57	  const updTime = formatTimeHHMM(freshness.estoque.updatedAt);
58	
59	  // Última bipagem: âmbar quando acima do threshold dentro da janela de
60	  // produção — MESMA janela/threshold do RAG da fábrica (TV_FACTORY_HOURS).
61	  const bip = factory.expedicoes.ultimaBipagem;
62	  const bipTime = formatTimeHHMM(bip);
63	  const bipAgo = formatAgoLabel(bip, now);
64	  const hour = now.getHours();
65	  const inProductionWindow =
66	    hour >= TV_FACTORY_HOURS.start && hour < TV_FACTORY_HOURS.end;
67	  const bipStale =
68	    inProductionWindow &&
69	    (bip == null ||
