1	/**
2	 * @module features/tv-dashboard/ui/TvExceptions
3	 *
4	 * Faixa de exceções do Painel TV (1229×248 — design.md §6.1): grid 2×4
5	 * preenchido coluna-primeiro, máx 7 itens + slot de overflow "+N outros",
6	 * cor SOMENTE na severidade e estado vazio explícito (nunca área em branco).
7	 */
8	
9	import { CheckCircle2, OctagonAlert, TriangleAlert } from 'lucide-react';
10	import type { TvException, TvExceptionsResult } from '../model/types';
11	
12	/**
13	 * Separa a linha em texto principal + valor à direita, por tipo de exceção
14	 * (design.md §6.1 — anatomia da linha).
15	 */
16	function splitException(ex: TvException): { text: string; value: string } {
17	  switch (ex.kind) {
18	    case 'stock-out':
19	      return {
20	        text: `${ex.produtoNome ?? 'Produto'} — ${ex.lojaNome ?? 'Loja'}`,
21	        value: '0 un',
22	      };
23	    case 'stock-low':
24	      return {
25	        text: `${ex.produtoNome ?? 'Produto'} — ${ex.lojaNome ?? 'Loja'}`,
26	        value: `${ex.quantidade ?? 0} · mín ${ex.quantidadeMinima ?? 0}`,
27	      };
28	    case 'no-movement': {
29	      const m = ex.message.match(/há \d+\s?h/);
30	      return {
31	        text: `${ex.lojaNome ?? 'Loja'} — sem bipagem`,
32	        value: m ? m[0] : '',
33	      };
34	    }
35	    case 'stale-data': {
36	      const m = ex.message.match(/desde \d{2}:\d{2}/);
37	      return {
38	        text: `${ex.lojaNome ?? 'Venda live'} — dado atrasado`,
39	        value: m ? m[0] : '',
40	      };
41	    }
42	  }
43	}
44	
45	/** Lista de exceções com estado vazio confirmado explicitamente. */
46	export function TvExceptions({ exceptions }: { exceptions: TvExceptionsResult }) {
47	  const { items, overflowCount, totalCount } = exceptions;
48	  const isEmpty = totalCount === 0;
49	
50	  return (
51	    <section
52	      className="flex h-full flex-col rounded-2xl border border-tv-border bg-tv-surface p-5"
53	      data-testid="tv-exceptions"
54	    >
55	      <div className="flex h-7 items-center justify-between">
56	        <h2 className="text-[24px] font-momma font-semibold uppercase tracking-[0.1em] text-tv-mut">
57	          EXCEÇÕES
58	        </h2>
59	        {totalCount > 0 && (
60	          <span className="font-tv-num text-[24px] font-medium leading-none text-tv-dim tabular-nums">
61	            {totalCount}
62	          </span>
63	        )}
64	      </div>
65	
66	      {isEmpty ? (
67	        <div
68	          className="flex h-full items-center justify-center gap-4"
69	          data-testid="tv-exceptions-empty"
70	        >
71	          <CheckCircle2 style={{ width: 44, height: 44 }} className="text-tv-sageup" aria-hidden />
72	          <p className="text-[28px] font-momma font-medium text-tv-mut">
73	            Nenhum alerta — tudo dentro do normal
74	          </p>
75	        </div>
76	      ) : (
77	        <ul className="mt-3 grid flex-1 grid-flow-col grid-cols-2 grid-rows-4 gap-x-6 gap-y-2">
78	          {items.map((ex) => {
79	            const { text, value } = splitException(ex);
80	            const isRed = ex.severity === 'red';
81	            return (
82	              <li
83	                key={ex.id}
84	                className={`tv-fade-in flex items-center gap-3 rounded-lg px-3 ${
85	                  isRed ? 'bg-tv-red/[0.08]' : 'bg-tv-amber/[0.06]'
86	                }`}
87	                data-testid="tv-exception-row"
88	                data-severity={ex.severity}
89	              >
90	                {isRed ? (
91	                  <OctagonAlert
92	                    style={{ width: 24, height: 24 }}
93	                    className="shrink-0 text-tv-red"
94	                    aria-hidden
95	                  />
96	                ) : (
97	                  <TriangleAlert
98	                    style={{ width: 24, height: 24 }}
99	                    className="shrink-0 text-tv-amber"
100	                    aria-hidden
101	                  />
102	                )}
103	                <span className="min-w-0 flex-1 truncate text-[24px] font-momma font-medium text-tv-text">
104	                  {text}
105	                </span>
106	                {value && (
107	                  <span
108	                    className={`shrink-0 font-tv-num text-[24px] font-medium tabular-nums ${
109	                      isRed ? 'text-tv-redsoft' : 'text-tv-amber'
110	                    }`}
111	                  >
112	                    {value}
113	                  </span>
114	                )}
115	              </li>
116	            );
117	          })}
118	          {overflowCount > 0 && (
119	            <li
120	              className="flex items-center rounded-lg px-3 text-[22px] font-momma text-tv-mut"
121	              data-testid="tv-exceptions-overflow"
122	            >
123	              + {overflowCount} outros alertas
124	            </li>
125	          )}
126	        </ul>
127	      )}
128	    </section>
129	  );
130	}
