1	/**
2	 * @module features/tv-dashboard/ui/TvChips
3	 *
4	 * Blocos visuais compartilhados do Painel TV: chip de delta semanal,
5	 * chip de fonte (ao vivo / atrasado / defasado Linx), chip de estado RAG,
6	 * badge de estoque e barra de % meta com tick de esperado.
7	 * Tokens e medidas: design.md §1.3–§1.6, §3 e §4.
8	 */
9	
10	import {
11	  ArrowDown,
12	  ArrowUp,
13	  CalendarClock,
14	  Check,
15	  OctagonAlert,
16	  RefreshCw,
17	  TriangleAlert,
18	} from 'lucide-react';
19	import type {
20	  TvFreshnessLevel,
21	  TvRagStatus,
22	  TvSalesChannel,
23	  TvStockAlertSummary,
24	} from '../model/types';
25	import { formatLaggedDateLabel } from '../model/tvMath';
26	import { clampPct, formatDeltaPct, type TvBarColor } from './tvFormat';
27	
28	// ─────────────────────────────────────────────────────────────────────────────
29	// Delta semanal (vs mesmo dia da semana passada — nunca "ontem")
30	// ─────────────────────────────────────────────────────────────────────────────
31	
32	interface TvDeltaChipProps {
33	  /** Delta % vs mesmo dia da semana anterior. */
34	  delta: number;
35	  /** Abreviação do dia comparado ("qua."). */
36	  weekdayLabel: string;
37	  /** Tamanho: hero (28px) ou card de loja (24px). */
38	  size: 'hero' | 'card';
39	}
40	
41	/**
42	 * Chip de delta semanal. Cor `tv-mut` sempre — exceto delta ≤ −15%,
43	 * que vira âmbar (design.md §3 zona 1). Positivo nunca ganha verde.
44	 */
45	export function TvDeltaChip({ delta, weekdayLabel, size }: TvDeltaChipProps) {
46	  const isAlert = delta <= -15;
47	  const colorCls = isAlert ? 'text-tv-amber' : 'text-tv-mut';
48	  const textCls = size === 'hero' ? 'text-[28px]' : 'text-[24px]';
49	  const iconPx = size === 'hero' ? 28 : 24;
50	  const Icon = delta < 0 ? ArrowDown : ArrowUp;
51	  return (
52	    <span
53	      className={`inline-flex items-center gap-1.5 rounded-full bg-tv-raised px-4 py-1.5 font-tv-num font-medium tabular-nums leading-none ${textCls} ${colorCls}`}
54	      data-testid="tv-delta-chip"
55	    >
56	      <Icon style={{ width: iconPx, height: iconPx }} aria-hidden />
57	      {formatDeltaPct(delta)} vs {weekdayLabel}
58	    </span>
59	  );
