61	
62	// ─────────────────────────────────────────────────────────────────────────────
63	// Chip de fonte (freshness honesta — design.md §4 item 1)
64	// ─────────────────────────────────────────────────────────────────────────────
65	
66	interface TvSourceChipProps {
67	  channel: TvSalesChannel;
68	  /** Freshness da fonte live (ignorado para canal Linx). */
69	  liveLevel: TvFreshnessLevel;
70	  /** Dia de referência (YYYY-MM-DD) do dado defasado Linx, ou null. */
71	  laggedDate?: string | null;
72	}
73	
74	/**
75	 * Chip de fonte do card: Degust fresco → "✓ ao vivo"; Degust atrasado →
76	 * "⟳ atrasado" (âmbar); Linx → selo NEUTRO "até DD/MM" (defasagem esperada
77	 * não é alarme).
78	 */
79	export function TvSourceChip({ channel, liveLevel, laggedDate }: TvSourceChipProps) {
80	  if (channel === 'linx-lagged') {
81	    return (
82	      <span
83	        className="inline-flex h-6 items-center gap-1.5 rounded-full bg-tv-raised px-3 text-[20px] font-momma font-medium leading-none text-tv-mut"
84	        data-testid="tv-source-chip-lagged"
85	      >
86	        <CalendarClock style={{ width: 18, height: 18 }} aria-hidden />
87	        {laggedDate ? formatLaggedDateLabel(laggedDate) : 'sem dados'}
88	      </span>
89	    );
90	  }
91	  if (liveLevel === 'fresh') {
92	    return (
93	      <span
94	        className="inline-flex h-6 items-center gap-1.5 rounded-full bg-tv-raised px-3 text-[20px] font-momma font-medium leading-none text-tv-sageup"
95	        data-testid="tv-source-chip-live"
96	      >
97	        <Check style={{ width: 18, height: 18 }} aria-hidden />
