102	  return (
103	    <span
104	      className="inline-flex h-6 items-center gap-1.5 rounded-full border border-tv-amber/40 bg-tv-raised px-3 text-[20px] font-momma font-medium leading-none text-tv-amber"
105	      data-testid="tv-source-chip-stale"
106	    >
107	      <RefreshCw style={{ width: 18, height: 18 }} aria-hidden />
108	      atrasado
109	    </span>
110	  );
111	}
112	
113	// ─────────────────────────────────────────────────────────────────────────────
114	// Chip de estado RAG (redundância não-cromática lível a 3m)
115	// ─────────────────────────────────────────────────────────────────────────────
116	
117	/** Chip "⚠ ATENÇÃO" / "⛔ CRÍTICO" do header do card. Nulo em estado ok. */
118	export function TvStateChip({ rag }: { rag: TvRagStatus }) {
119	  if (rag === 'ok') return null;
120	  if (rag === 'red') {
121	    return (
122	      <span
123	        className="inline-flex h-6 items-center gap-1.5 rounded-full bg-tv-red/15 px-3 text-[20px] font-momma font-medium leading-none text-tv-redsoft"
124	        data-testid="tv-state-chip-red"
125	      >
126	        <OctagonAlert style={{ width: 18, height: 18 }} aria-hidden />
127	        CRÍTICO
128	      </span>
129	    );
130	  }
131	  return (
132	    <span
133	      className="inline-flex h-6 items-center gap-1.5 rounded-full bg-tv-amber/15 px-3 text-[20px] font-momma font-medium leading-none text-tv-amber"
134	      data-testid="tv-state-chip-amber"
135	    >
