142	// ─────────────────────────────────────────────────────────────────────────────
143	// Badge de estoque (contagem; vermelho absorve âmbar quando há ambos)
144	// ─────────────────────────────────────────────────────────────────────────────
145	
146	/**
147	 * Badge de alerta de estoque do header. Se houver zerados E abaixo do
148	 * mínimo, mostra só o vermelho com a SOMA (design.md §4 item 1).
149	 */
150	export function TvStockBadge({ estoque }: { estoque: TvStockAlertSummary }) {
151	  const total = estoque.zerados + estoque.abaixoMinimo;
152	  if (total === 0) return null;
153	  if (estoque.zerados > 0) {
154	    return (
155	      <span
156	        className="inline-flex h-6 items-center gap-1.5 rounded-full bg-tv-red/15 px-3 text-[20px] font-tv-num font-medium leading-none text-tv-redsoft tabular-nums"
157	        data-testid="tv-stock-badge-red"
158	      >
159	        <OctagonAlert style={{ width: 18, height: 18 }} aria-hidden />
160	        {total}
161	      </span>
162	    );
163	  }
164	  return (
165	    <span
166	      className="inline-flex h-6 items-center gap-1.5 rounded-full bg-tv-amber/15 px-3 text-[20px] font-tv-num font-medium leading-none text-tv-amber tabular-nums"
167	      data-testid="tv-stock-badge-amber"
168	    >
169	      <TriangleAlert style={{ width: 18, height: 18 }} aria-hidden />
170	      {total}
171	    </span>
