174	
175	// ─────────────────────────────────────────────────────────────────────────────
176	// Barra de % meta com tick de "esperado agora"
177	// ─────────────────────────────────────────────────────────────────────────────
178	
179	const BAR_FILL_CLS: Record<TvBarColor, string> = {
180	  sage: 'bg-tv-sage',
181	  amber: 'bg-tv-amber',
182	  red: 'bg-tv-red',
183	};
184	
185	interface TvMetaBarProps {
186	  /** % do dia COMPLETO da meta já atingido (preenchimento), ou null. */
187	  fillPct: number | null;
188	  /** Posição do tick de "esperado agora" (0–100), ou null para ocultar. */
189	  expectedPct: number | null;
190	  /** Cor semântica do preenchimento (estado de venda — design.md §1.6). */
191	  color: TvBarColor;
192	  /** Altura da barra: hero 20px, card 12px. */
193	  size: 'hero' | 'card';
194	}
195	
196	/**
197	 * Barra horizontal de % meta com trilho `tv-track`, preenchimento colorido
198	 * por estado de venda e tick vertical de "esperado agora" (pró-rata).
199	 * Transição de width 600ms ease-out (design.md §8.1.3).
200	 */
201	export function TvMetaBar({ fillPct, expectedPct, color, size }: TvMetaBarProps) {
202	  const heightCls = size === 'hero' ? 'h-5' : 'h-3';
203	  const tick =
204	    size === 'hero'
205	      ? { width: 3, height: 28, offset: -4 }
