207	  return (
208	    <div className={`relative w-full rounded-full bg-tv-track ${heightCls}`} data-testid="tv-meta-bar">
209	      {fillPct != null && (
210	        <div
211	          className={`absolute inset-y-0 left-0 rounded-full transition-[width] [transition-duration:600ms] ease-out motion-reduce:transition-none ${BAR_FILL_CLS[color]}`}
212	          style={{ width: `${clampPct(fillPct)}%` }}
