1	/**
2	 * @module features/tv-dashboard/ui/TvMetas.page
3	 *
4	 * Página `/tv/metas` (admin): grade lojas × dias da semana (dom–sáb) para
5	 * cadastrar a meta diária de vendas em R$ (`metas_vendas`, upsert por
6	 * loja_id+dia_semana). Usa o layout normal do app — o DashboardLayout é
7	 * aplicado na rota (App.tsx), como nas demais páginas.
8	 */
9	
10	import { useEffect, useMemo, useRef, useState } from 'react';
11	import { useNavigate } from 'react-router-dom';
12	import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
13	import { ArrowLeft, MonitorPlay, Save } from 'lucide-react';
14	import { toast } from 'sonner';
15	import { supabase } from '@/integrations/supabase/client';
16	import { Button } from '@/shared/ui/button';
17	import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/shared/ui/card';
18	import { Input } from '@/shared/ui/input';
19	import {
20	  Table,
21	  TableBody,
22	  TableCell,
23	  TableHead,
24	  TableHeader,
25	  TableRow,
26	} from '@/shared/ui/table';
27	import { tvDashboardKeys } from '../model/useTvDashboardData';
28	
29	/** Cabeçalhos das colunas (índice = `Date.getDay()`: 0=domingo). */
30	const WEEKDAYS = ['Dom', 'Seg', 'Ter', 'Qua', 'Qui', 'Sex', 'Sáb'] as const;
31	
32	interface MetasLoja {
33	  id: number;
34	  nome: string;
35	}
36	
37	interface MetaRow {
38	  loja_id: number;
39	  dia_semana: number;
40	  valor_meta: number;
41	}
42	
43	function cellKey(lojaId: number, dia: number): string {
44	  return `${lojaId}:${dia}`;
45	}
46	
47	function isFactoryTipo(tipo: string | null): boolean {
48	  const t = (tipo ?? '').toLowerCase();
49	  return t.startsWith('fabrica') || t.startsWith('fábrica');
50	}
51	
52	async function fetchLojasVenda(): Promise<MetasLoja[]> {
53	  const { data, error } = await supabase
54	    .from('lojas')
55	    .select('id, nome, tipo')
56	    .eq('ativo', true)
57	    .order('id');
58	  if (error) throw error;
59	  return (data ?? [])
60	    .filter((l) => !isFactoryTipo(l.tipo))
61	    .map((l) => ({ id: l.id, nome: l.nome }));
62	}
63	
64	async function fetchMetas(): Promise<MetaRow[]> {
65	  const { data, error } = await supabase
66	    .from('metas_vendas')
67	    .select('loja_id, dia_semana, valor_meta')
68	    .limit(1000);
69	  if (error) throw error;
70	  return data ?? [];
71	}
72	
73	/** Grade de metas do Painel TV (admin only — rota protegida em App.tsx). */
74	export default function TvMetasPage() {
75	  const navigate = useNavigate();
76	  const queryClient = useQueryClient();
77	
78	  const lojasQuery = useQuery({ queryKey: ['tv-metas', 'lojas'], queryFn: fetchLojasVenda });
79	  const metasQuery = useQuery({ queryKey: ['tv-metas', 'valores'], queryFn: fetchMetas });
80	
81	  // Valores dos inputs (string p/ digitação livre), keyed `lojaId:dia`.
82	  // null = ainda não inicializado a partir do banco (NUNCA derivar upserts
83	  // de zeramento antes da inicialização — risco de apagar metas).
84	  const [values, setValues] = useState<Record<string, string> | null>(null);
85	  const initialized = useRef(false);
86	  useEffect(() => {
87	    if (initialized.current || !metasQuery.data) return;
88	    initialized.current = true;
89	    const next: Record<string, string> = {};
90	    for (const meta of metasQuery.data) {
91	      next[cellKey(meta.loja_id, meta.dia_semana)] =
92	        meta.valor_meta > 0 ? String(meta.valor_meta) : '';
93	    }
94	    setValues(next);
95	  }, [metasQuery.data]);
96	
97	  const saveMutation = useMutation({
98	    mutationFn: async (rows: MetaRow[]) => {
99	      const { error } = await supabase
100	        .from('metas_vendas')
101	        .upsert(rows, { onConflict: 'loja_id,dia_semana' });
102	      if (error) throw error;
103	    },
104	    onSuccess: () => {
105	      toast.success('Metas salvas com sucesso');
106	      queryClient.invalidateQueries({ queryKey: ['tv-metas', 'valores'] });
107	      queryClient.invalidateQueries({ queryKey: tvDashboardKeys.metas() });
108	    },
109	    onError: (error: Error) => {
110	      toast.error('Erro ao salvar metas', {
111	        description: error.message || 'Tente novamente em instantes.',
112	      });
113	    },
114	  });
115	
116	  // Células que TÊM meta (>0) no banco — pra detectar célula esvaziada
117	  const persistedKeys = useMemo(() => {
118	    const keys = new Set<string>();
119	    for (const meta of metasQuery.data ?? []) {
120	      if (meta.valor_meta > 0) keys.add(cellKey(meta.loja_id, meta.dia_semana));
121	    }
122	    return keys;
123	  }, [metasQuery.data]);
124	
125	  const rows = useMemo(() => {
126	    if (values == null) return [];
127	    const out: MetaRow[] = [];
128	    for (const loja of lojasQuery.data ?? []) {
129	      for (let dia = 0; dia <= 6; dia++) {
130	        const key = cellKey(loja.id, dia);
131	        const raw = values[key];
132	        if (raw == null || raw.trim() === '') {
133	          // Célula esvaziada que TINHA meta no banco → upsert com 0
134	          // (0 = sem meta; o data layer trata valor_meta <= 0 como null).
135	          // Células que sempre estiveram vazias NÃO são enviadas.
136	          if (persistedKeys.has(key)) {
137	            out.push({ loja_id: loja.id, dia_semana: dia, valor_meta: 0 });
138	          }
139	          continue;
140	        }
141	        const parsed = Number(raw.replace(',', '.'));
142	        if (!Number.isFinite(parsed) || parsed < 0) continue;
143	        out.push({ loja_id: loja.id, dia_semana: dia, valor_meta: parsed });
144	      }
145	    }
146	    return out;
147	  }, [lojasQuery.data, values, persistedKeys]);
148	
149	  const isLoading = lojasQuery.isLoading || metasQuery.isLoading;
150	
151	  return (
152	    <div className="space-y-6 p-4 md:p-6" data-testid="tv-metas-page">
153	      <div className="flex flex-wrap items-center justify-between gap-3">
154	        <div className="flex items-center gap-3">
155	          <Button
156	            variant="outline"
157	            size="icon"
158	            onClick={() => navigate('/tv')}
159	            data-mia-action="voltar-painel-tv"
160	            aria-label="Voltar para o Painel TV"
161	          >
162	            <ArrowLeft className="h-4 w-4" />
163	          </Button>
164	          <div>
165	            <h1 className="flex items-center gap-2 text-2xl font-bold">
166	              <MonitorPlay className="h-6 w-6" />
167	              Metas do Painel TV
168	            </h1>
169	            <p className="text-sm text-muted-foreground">
170	              Meta diária de vendas (R$) por loja e dia da semana — usada no % pró-rata do painel.
171	            </p>
172	          </div>
173	        </div>
174	        <Button
175	          onClick={() => saveMutation.mutate(rows)}
176	          disabled={saveMutation.isPending || isLoading || rows.length === 0}
177	          data-mia-action="salvar-metas-painel-tv"
178	        >
179	          <Save className="mr-2 h-4 w-4" />
180	          {saveMutation.isPending ? 'Salvando…' : 'Salvar metas'}
181	        </Button>
182	      </div>
183	
184	      <Card>
185	        <CardHeader>
186	          <CardTitle>Grade de metas</CardTitle>
187	          <CardDescription>
188	            Deixe em branco os dias sem meta — o painel mostra "sem meta cadastrada".
189	          </CardDescription>
190	        </CardHeader>
191	        <CardContent>
192	          {isLoading ? (
193	            <p className="py-8 text-center text-sm text-muted-foreground">
194	              Carregando metas…
195	            </p>
196	          ) : (lojasQuery.data ?? []).length === 0 ? (
197	            <p className="py-8 text-center text-sm text-muted-foreground">
198	              Nenhuma loja ativa encontrada.
199	            </p>
200	          ) : (
201	            <div className="overflow-x-auto">
202	              <Table>
203	                <TableHeader>
204	                  <TableRow>
205	                    <TableHead className="min-w-[160px]">Loja</TableHead>
206	                    {WEEKDAYS.map((dia) => (
207	                      <TableHead key={dia} className="min-w-[110px] text-center">
208	                        {dia}
209	                      </TableHead>
210	                    ))}
211	                  </TableRow>
212	                </TableHeader>
213	                <TableBody>
214	                  {(lojasQuery.data ?? []).map((loja) => (
215	                    <TableRow key={loja.id} data-testid="tv-metas-row">
216	                      <TableCell className="font-medium">{loja.nome}</TableCell>
217	                      {WEEKDAYS.map((_, dia) => {
218	                        const key = cellKey(loja.id, dia);
219	                        return (
220	                          <TableCell key={key} className="text-center">
221	                            <Input
222	                              type="number"
223	                              min={0}
224	                              step={50}
225	                              inputMode="decimal"
226	                              placeholder="R$"
227	                              className="mx-auto w-24 text-right"
228	                              value={values?.[key] ?? ''}
229	                              onChange={(e) =>
230	                                setValues((prev) => ({ ...prev, [key]: e.target.value }))
231	                              }
232	                              data-mia-field={`meta-${loja.id}-dia-${dia}`}
233	                              aria-label={`Meta de ${loja.nome} — ${WEEKDAYS[dia]}`}
234	                            />
235	                          </TableCell>
236	                        );
237	                      })}
238	                    </TableRow>
239	                  ))}
240	                </TableBody>
241	              </Table>
242	            </div>
243	          )}
244	        </CardContent>
245	      </Card>
246	    </div>
247	  );
248	}
