/**
 * @module features/tv-dashboard/ui/TvChips
 *
 * Blocos visuais compartilhados do Painel TV: chip de delta semanal,
 * chip de fonte (ao vivo / atrasado / defasado Linx), chip de estado RAG,
 * badge de estoque e barra de % meta com tick de esperado.
 * Linguagem v2 (glassmorphism Momma): design.md §1.3–§1.6, §3 e §4.
 */

import {
  ArrowDown,
  ArrowUp,
  CalendarClock,
  Check,
  OctagonAlert,
  RefreshCw,
  TriangleAlert,
} from 'lucide-react';
import type {
  TvFreshnessLevel,
  TvRagStatus,
  TvSalesChannel,
  TvStockAlertSummary,
} from '../model/types';
import { formatLaggedDateLabel } from '../model/tvMath';
import { clampPct, formatDeltaPct, type TvBarColor } from './tvFormat';

// ─────────────────────────────────────────────────────────────────────────────
// Delta semanal (vs mesmo dia da semana passada — nunca "ontem")
// ─────────────────────────────────────────────────────────────────────────────

interface TvDeltaChipProps {
  /** Delta % vs mesmo dia da semana anterior. */
  delta: number;
  /** Abreviação do dia comparado ("qua."). */
  weekdayLabel: string;
  /** Tamanho: hero (28px) ou card de loja (24px). */
  size: 'hero' | 'card';
}

/**
 * Chip de delta semanal. Neutro (pill sage suave) sempre — exceto delta
 * ≤ −15%, que vira âmbar (design.md §3 zona 1). Positivo nunca ganha verde.
 */
export function TvDeltaChip({ delta, weekdayLabel, size }: TvDeltaChipProps) {
  const isAlert = delta <= -15;
  const colorCls = isAlert
    ? 'bg-amber-50 text-amber-600'
    : 'bg-[#57715B]/8 text-[#5F6F63]';
  const textCls = size === 'hero' ? 'text-[28px]' : 'text-[24px]';
  const iconPx = size === 'hero' ? 28 : 24;
  const Icon = delta < 0 ? ArrowDown : ArrowUp;
  return (
    <span
      className={`inline-flex items-center gap-1.5 rounded-full px-4 py-1.5 font-momma font-medium tabular-nums leading-none ${textCls} ${colorCls}`}
      data-testid="tv-delta-chip"
    >
      <Icon style={{ width: iconPx, height: iconPx }} aria-hidden />
      {formatDeltaPct(delta)} vs {weekdayLabel}
    </span>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Chip de fonte (freshness honesta — design.md §4 item 1)
// ─────────────────────────────────────────────────────────────────────────────

interface TvSourceChipProps {
  channel: TvSalesChannel;
  /** Freshness da fonte live (ignorado para canal Linx). */
  liveLevel: TvFreshnessLevel;
  /** Dia de referência (YYYY-MM-DD) do dado defasado Linx, ou null. */
  laggedDate?: string | null;
}

/**
 * Chip de fonte do card: Degust fresco → "✓ ao vivo" (emerald); Degust
 * atrasado → "⟳ atrasado" (âmbar); Linx → selo NEUTRO "até DD/MM"
 * (defasagem esperada não é alarme).
 */
export function TvSourceChip({ channel, liveLevel, laggedDate }: TvSourceChipProps) {
  if (channel === 'linx-lagged') {
    return (
      <span
        className="inline-flex h-6 items-center gap-1.5 rounded-full bg-[#57715B]/8 px-3 text-[20px] font-momma font-medium leading-none text-[#5F6F63]"
        data-testid="tv-source-chip-lagged"
      >
        <CalendarClock style={{ width: 18, height: 18 }} aria-hidden />
        {laggedDate ? formatLaggedDateLabel(laggedDate) : 'sem dados'}
      </span>
    );
  }
  if (liveLevel === 'fresh') {
    return (
      <span
        className="inline-flex h-6 items-center gap-1.5 rounded-full bg-emerald-50 px-3 text-[20px] font-momma font-medium leading-none text-emerald-600"
        data-testid="tv-source-chip-live"
      >
        <Check style={{ width: 18, height: 18 }} aria-hidden />
        ao vivo
      </span>
    );
  }
  return (
    <span
      className="inline-flex h-6 items-center gap-1.5 rounded-full border border-amber-400/40 bg-amber-50 px-3 text-[20px] font-momma font-medium leading-none text-amber-600"
      data-testid="tv-source-chip-stale"
    >
      <RefreshCw style={{ width: 18, height: 18 }} aria-hidden />
      atrasado
    </span>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Chip de estado RAG (redundância não-cromática lível a 3m)
// ─────────────────────────────────────────────────────────────────────────────

/** Chip "⚠ ATENÇÃO" / "⛔ CRÍTICO" do header do card. Nulo em estado ok. */
export function TvStateChip({ rag }: { rag: TvRagStatus }) {
  if (rag === 'ok') return null;
  if (rag === 'red') {
    return (
      <span
        className="inline-flex h-6 items-center gap-1.5 rounded-full bg-red-50 px-3 text-[20px] font-momma font-medium leading-none text-red-600"
        data-testid="tv-state-chip-red"
      >
        <OctagonAlert style={{ width: 18, height: 18 }} aria-hidden />
        CRÍTICO
      </span>
    );
  }
  return (
    <span
      className="inline-flex h-6 items-center gap-1.5 rounded-full bg-amber-50 px-3 text-[20px] font-momma font-medium leading-none text-amber-600"
      data-testid="tv-state-chip-amber"
    >
      <TriangleAlert style={{ width: 18, height: 18 }} aria-hidden />
      ATENÇÃO
    </span>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Badge de estoque (contagem; vermelho absorve âmbar quando há ambos)
// ─────────────────────────────────────────────────────────────────────────────

/**
 * Badge de alerta de estoque do header. Se houver zerados E abaixo do
 * mínimo, mostra só o vermelho com a SOMA (design.md §4 item 1).
 */
export function TvStockBadge({ estoque }: { estoque: TvStockAlertSummary }) {
  const total = estoque.zerados + estoque.abaixoMinimo;
  if (total === 0) return null;
  if (estoque.zerados > 0) {
    return (
      <span
        className="inline-flex h-6 items-center gap-1.5 rounded-full bg-red-50 px-3 text-[20px] font-momma font-medium leading-none text-red-600 tabular-nums"
        data-testid="tv-stock-badge-red"
      >
        <OctagonAlert style={{ width: 18, height: 18 }} aria-hidden />
        {total}
      </span>
    );
  }
  return (
    <span
      className="inline-flex h-6 items-center gap-1.5 rounded-full bg-amber-50 px-3 text-[20px] font-momma font-medium leading-none text-amber-600 tabular-nums"
      data-testid="tv-stock-badge-amber"
    >
      <TriangleAlert style={{ width: 18, height: 18 }} aria-hidden />
      {total}
    </span>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Barra de % meta com tick de "esperado agora"
// ─────────────────────────────────────────────────────────────────────────────

const BAR_FILL_CLS: Record<TvBarColor, string> = {
  sage: 'bg-gradient-to-r from-[#57715B] to-[#4a6250]',
  amber: 'bg-gradient-to-r from-amber-400 to-amber-500',
  red: 'bg-gradient-to-r from-red-400 to-red-500',
};

interface TvMetaBarProps {
  /** % do dia COMPLETO da meta já atingido (preenchimento), ou null. */
  fillPct: number | null;
  /** Posição do tick de "esperado agora" (0–100), ou null para ocultar. */
  expectedPct: number | null;
  /** Cor semântica do preenchimento (estado de venda — design.md §1.6). */
  color: TvBarColor;
  /** Altura da barra: hero 20px, card 12px. */
  size: 'hero' | 'card';
}

/**
 * Barra horizontal de % meta: trilha sage suave (`#57715B/10`),
 * preenchimento em gradiente por estado de venda e tick DOURADO de
 * "esperado agora" (pró-rata). Transição de width 600ms ease-out (§8.1.3).
 */
export function TvMetaBar({ fillPct, expectedPct, color, size }: TvMetaBarProps) {
  const heightCls = size === 'hero' ? 'h-5' : 'h-3';
  const tick =
    size === 'hero'
      ? { width: 3, height: 28, offset: -4 }
      : { width: 2, height: 20, offset: -4 };
  return (
    <div
      className={`relative w-full rounded-full bg-[#57715B]/10 ${heightCls}`}
      data-testid="tv-meta-bar"
    >
      {fillPct != null && (
        <div
          className={`absolute inset-y-0 left-0 rounded-full transition-[width] [transition-duration:600ms] ease-out motion-reduce:transition-none ${BAR_FILL_CLS[color]}`}
          style={{ width: `${clampPct(fillPct)}%` }}
          data-testid="tv-meta-bar-fill"
        />
      )}
      {expectedPct != null && (
        <div
          className="absolute rounded-full bg-[#C5A065]"
          style={{
            left: `calc(${clampPct(expectedPct)}% - ${tick.width / 2}px)`,
            top: tick.offset,
            width: tick.width,
            height: tick.height,
          }}
          data-testid="tv-meta-bar-tick"
        />
      )}
    </div>
  );
}

/**
 * @module features/tv-dashboard/ui/TvHero
 *
 * Hero do Painel TV (1856×152 — design.md §3): vendas da rede hoje +
 * delta vs mesmo dia da semana passada, barra de % meta pró-rata com tick
 * de "esperado agora", contador de alertas críticos e relógio + freshness.
 * Linguagem v2: wordmark MOMMA dourado + título serif sobre vidro branco.
 */

import { Check, OctagonAlert, RefreshCw } from 'lucide-react';
import type { TvFreshness, TvNetworkSummary } from '../model/types';
import { formatCompactBRL } from '../model/tvMath';
import { TvDeltaChip, TvMetaBar } from './TvChips';
import {
  WEEKDAY_ABBR,
  expectedPctNow,
  formatTimeHHMM,
  metaBarColorFromRatio,
} from './tvFormat';
import { useCountUp } from './useCountUp';

interface TvHeroProps {
  network: TvNetworkSummary | null;
  freshness: TvFreshness;
  now: Date;
}

/** Hero da rede: 4 zonas em grid fixo (600/460/360/1fr — design.md §3). */
export function TvHero({ network, freshness, now }: TvHeroProps) {
  const vendas = useCountUp(network?.vendasHoje ?? 0);
  const hasData = network != null;

  // Barra: preenchimento = % do dia COMPLETO da meta; tick = esperado agora.
  const fullDayPct =
    network && network.metaDia != null && network.metaDia > 0
      ? (network.vendasHoje / network.metaDia) * 100
      : null;
  const expected = expectedPctNow(now);
  const ratio = network?.pctMetaProRata != null ? network.pctMetaProRata / 100 : null;
  const barColor = metaBarColorFromRatio(ratio, now);

  const alertas = network?.alertasCriticos ?? 0;
  const alertasAnim = Math.round(useCountUp(alertas));

  const liveFresh = freshness.vendasLive.level === 'fresh';
  const liveTime = formatTimeHHMM(freshness.vendasLive.updatedAt);

  return (
    <header className="grid grid-cols-[600px_460px_360px_1fr] items-end gap-8 border-b border-[#C5A065]/25 pb-4">
      {/* Zona 1 — vendas da rede */}
      <div>
        <div className="flex items-baseline gap-3">
          <span className="text-[20px] font-momma font-bold uppercase tracking-[0.3em] text-[#C5A065]">
            MOMMA
          </span>
          <span className="font-serif text-[26px] font-semibold tracking-tight text-[#2D362E]">
            Rede hoje
          </span>
        </div>
        <div className="mt-1 flex items-end gap-4">
          <span
            className="font-momma text-[96px] font-bold leading-none text-[#2D362E] tabular-nums"
            data-testid="tv-hero-sales"
          >
            {hasData ? formatCompactBRL(vendas) : '—'}
          </span>
          {network?.deltaSemana != null && (
            <span className="pb-2">
              <TvDeltaChip
                delta={network.deltaSemana}
                weekdayLabel={WEEKDAY_ABBR[now.getDay()]}
                size="hero"
              />
            </span>
          )}
        </div>
      </div>

      {/* Zona 2 — % da meta (pró-rata) */}
      <div>
        <span className="text-[22px] font-momma font-medium uppercase tracking-wider text-[#5F6F63]">
          % DA META (PRÓ-RATA)
        </span>
        <div className="mt-3 w-[420px]">
          <TvMetaBar
            fillPct={fullDayPct}
            expectedPct={fullDayPct != null ? expected : null}
            color={barColor}
            size="hero"
          />
        </div>
        <div className="mt-2 flex items-baseline gap-4">
          {fullDayPct != null ? (
            <>
              <span className="font-momma text-[40px] font-bold leading-none text-[#2D362E] tabular-nums">
                {Math.round(fullDayPct)}%
              </span>
              <span className="text-[22px] font-momma text-[#7C887E]">
                esperado {expected}%
              </span>
            </>
          ) : (
            <span className="text-[22px] font-momma text-[#7C887E]">
              sem meta cadastrada
            </span>
          )}
        </div>
      </div>

      {/* Zona 3 — alertas críticos */}
      <div>
        <span className="text-[22px] font-momma font-medium uppercase tracking-wider text-[#5F6F63]">
          ALERTAS CRÍTICOS
        </span>
        <div className="mt-1 flex items-center gap-3" data-testid="tv-hero-alerts">
          {alertas === 0 ? (
            <>
              <Check style={{ width: 40, height: 40 }} className="text-emerald-500" aria-hidden />
              <span className="font-momma text-[72px] font-bold leading-none text-emerald-600 tabular-nums">
                0
              </span>
            </>
          ) : (
            <>
              <OctagonAlert style={{ width: 48, height: 48 }} className="text-red-500" aria-hidden />
              <span className="font-momma text-[72px] font-bold leading-none text-red-600 tabular-nums">
                {alertasAnim}
              </span>
            </>
          )}
        </div>
      </div>

      {/* Zona 4 — relógio + freshness (à direita) */}
      <div className="flex flex-col items-end gap-2">
        <span className="font-momma text-[64px] font-light leading-none text-[#2D362E] tabular-nums">
          {formatTimeHHMM(now)}
        </span>
        {liveFresh ? (
          <span className="inline-flex items-center gap-2 rounded-full bg-emerald-50 px-4 py-1 text-[22px] font-momma font-medium text-emerald-600">
            <Check style={{ width: 20, height: 20 }} aria-hidden />
            ao vivo{liveTime ? ` · ${liveTime}` : ''}
          </span>
        ) : (
          <span className="inline-flex items-center gap-2 rounded-full border border-amber-400/40 bg-amber-50 px-4 py-1 text-[22px] font-momma font-medium text-amber-600">
            <RefreshCw style={{ width: 20, height: 20 }} aria-hidden />
            atrasado{liveTime ? ` · último ${liveTime}` : ''}
          </span>
        )}
      </div>
    </header>
  );
}

/**
 * @module features/tv-dashboard/ui/TvStoreCard
 *
 * Card de loja do Painel TV (602×280 — design.md §4): vendas do dia (ou
 * defasadas com selo honesto), barra de % meta, mini-stats e borda RAG
 * com redundância não-cromática (glow + chip de estado).
 * Chassi v2: glass premium (vidro branco + gradiente interno dourado sutil).
 */

import { ArrowDownRight, ArrowUpRight } from 'lucide-react';
import type { TvFreshnessLevel, TvStoreData } from '../model/types';
import { formatCompactBRL, parseBrDateTime, parseIsoDateLocal } from '../model/tvMath';
import {
  TvDeltaChip,
  TvMetaBar,
  TvSourceChip,
  TvStateChip,
  TvStockBadge,
} from './TvChips';
import {
  WEEKDAY_ABBR,
  expectedPctNow,
  formatInt,
  formatTicketBRL,
  formatTimeHHMM,
  formatWeekdayDayMonth,
  metaBarColorFromRatio,
} from './tvFormat';
import { useCountUp } from './useCountUp';

interface TvStoreCardProps {
  store: TvStoreData;
  /** Freshness consolidado da fonte de vendas live (chip "ao vivo"/"atrasado"). */
  liveLevel: TvFreshnessLevel;
  now: Date;
}

/**
 * Borda + glow por estado RAG (design.md §4 — sinal lível a 5m).
 * Normal = vidro calmo; ÂMBAR/CRÍTICO ganham borda colorida + glow suave.
 */
const RAG_FRAME: Record<TvStoreData['rag'], string> = {
  ok: 'border border-[#57715B]/10 shadow-[0_8px_32px_rgba(0,0,0,0.06)]',
  amber: 'border-2 border-amber-400/60 shadow-[0_8px_32px_rgba(245,158,11,0.18)]',
  red: 'border-2 border-red-400/70 shadow-[0_8px_32px_rgba(229,72,77,0.15)]',
};

/** Card de loja: cobre canal Degust live e Linx defasado. */
export function TvStoreCard({ store, liveLevel, now }: TvStoreCardProps) {
  const { vendas, metaDia, channel } = store;
  const isLive = channel === 'degust-live';
  const valorAnim = useCountUp(vendas?.valor ?? 0);
  const cuponsAnim = Math.round(useCountUp(vendas?.cupons ?? 0));

  // Barra: preenchimento = % do dia COMPLETO; tick pró-rata só no canal live
  const fullDayPct =
    vendas != null && metaDia != null && metaDia > 0
      ? (vendas.valor / metaDia) * 100
      : null;
  const expected = isLive ? expectedPctNow(now) : null;
  const barColor = isLive
    ? metaBarColorFromRatio(store.pctMeta != null ? store.pctMeta / 100 : null, now)
    : 'sage';

  const bipTime = formatTimeHHMM(store.movimentacao.ultimaBipagem);
  const refDate = vendas ? parseIsoDateLocal(vendas.dataReferencia) : null;

  // Caption sob as vendas (design.md §4 item 4)
  let caption: string;
  if (vendas == null) {
    caption = 'sem dado de venda disponível';
  } else if (isLive) {
    // `ultima_atualizacao` do Degust vem "DD/MM/YYYY HH:mm:ss" — parser
    // dedicado pt-BR (new Date() falha para dia > 12).
    const upd = formatTimeHHMM(parseBrDateTime(vendas.atualizadoEm));
    caption = `hoje${upd ? ` · atualizado ${upd}` : ''}${bipTime ? ` · bip ${bipTime}` : ''}`;
  } else {
    caption = `${refDate ? formatWeekdayDayMonth(refDate) : ''} — último dia com dados${bipTime ? ` · bip ${bipTime}` : ''}`;
  }

  return (
    <section
      className={`relative overflow-hidden rounded-[2rem] bg-white/60 p-5 backdrop-blur-xl saturate-150 transition-[border-color,box-shadow] [transition-duration:400ms] motion-reduce:transition-none ${RAG_FRAME[store.rag]}`}
      data-testid="tv-store-card"
      data-rag={store.rag}
    >
      {/* Gradiente interno sutil (assinatura glass premium) */}
      <div
        className="pointer-events-none absolute inset-0 bg-gradient-to-br from-white/40 via-transparent to-[#C5A065]/5"
        aria-hidden
      />

      <div className="relative z-10 flex h-full flex-col">
        {/* Header: nome + chips */}
        <div className="flex h-8 items-center justify-between gap-3">
          <h2 className="truncate text-[28px] font-momma font-semibold leading-8 text-[#2D362E]">
            {store.nome}
          </h2>
          <div className="flex shrink-0 items-center gap-2">
            <TvStateChip rag={store.rag} />
            <TvStockBadge estoque={store.estoque} />
            <TvSourceChip
              channel={channel}
              liveLevel={liveLevel}
              laggedDate={vendas?.dataReferencia ?? null}
            />
          </div>
        </div>

        {/* Vendas (64px) + delta */}
        <div className="mt-1.5 flex items-end gap-4">
          <span
            className={`font-momma text-[64px] font-bold leading-none tabular-nums ${vendas ? 'text-[#2D362E]' : 'text-[#7C887E]'}`}
            data-testid="tv-store-sales"
          >
            {vendas ? formatCompactBRL(valorAnim) : '—'}
          </span>
          {store.deltaSemana != null && refDate != null && (
            <span className="pb-1">
              <TvDeltaChip
                delta={store.deltaSemana}
                weekdayLabel={WEEKDAY_ABBR[refDate.getDay()]}
                size="card"
              />
            </span>
          )}
        </div>
        <p className="mt-1 text-[20px] font-momma font-medium leading-tight text-[#7C887E]">
          {caption}
        </p>

        {/* Barra de meta */}
        <div className="mt-2">
          <TvMetaBar
            fillPct={fullDayPct}
            expectedPct={fullDayPct != null ? expected : null}
            color={barColor}
            size="card"
          />
          <p className="mt-1.5 text-[22px] font-momma leading-tight">
            {fullDayPct != null ? (
              isLive ? (
                <>
                  <span className="font-medium text-[#5F6F63]">
                    {Math.round(fullDayPct)}% da meta
                  </span>
                  <span className="text-[#7C887E]"> · esperado {expected}%</span>
                </>
              ) : (
                <span className="font-medium text-[#5F6F63]">
                  {Math.round(fullDayPct)}% da meta de{' '}
                  {refDate ? WEEKDAY_ABBR[refDate.getDay()] : '—'}
                </span>
              )
            ) : (
              <span className="text-[#7C887E]">sem meta cadastrada</span>
            )}
          </p>
        </div>

        {/* Mini-stats */}
        <div className="mt-auto grid grid-cols-3 gap-4">
          <div>
            <p className="text-[22px] font-momma font-medium uppercase tracking-wider text-[#5F6F63]">
              CUPONS
            </p>
            <p className="mt-0.5 font-momma text-[32px] font-medium leading-none text-[#2D362E] tabular-nums">
              {vendas?.cupons != null ? formatInt(cuponsAnim) : '—'}
            </p>
          </div>
          <div>
            <p className="text-[22px] font-momma font-medium uppercase tracking-wider text-[#5F6F63]">
              TICKET
            </p>
            <p className="mt-0.5 font-momma text-[32px] font-medium leading-none text-[#2D362E] tabular-nums">
              {vendas?.ticketMedio != null ? formatTicketBRL(vendas.ticketMedio) : '—'}
            </p>
          </div>
          <div>
            <p className="text-[22px] font-momma font-medium uppercase tracking-wider text-[#5F6F63]">
              FLUXO
            </p>
            <p className="mt-0.5 flex items-center gap-1 font-momma text-[28px] font-medium leading-none text-[#2D362E] tabular-nums">
              <ArrowUpRight style={{ width: 22, height: 22 }} className="text-[#5F6F63]" aria-hidden />
              {store.movimentacao.entradas}
              <ArrowDownRight
                style={{ width: 22, height: 22 }}
                className="ml-2 text-[#5F6F63]"
                aria-hidden
              />
              {store.movimentacao.saidas}
            </p>
          </div>
        </div>
      </div>
    </section>
  );
}

/**
 * @module features/tv-dashboard/ui/TvFabricaCard
 *
 * Card diferenciado da fábrica (602×280, posição 6 — design.md §5):
 * produção do dia (com data de referência explícita quando fallback),
 * expedições, última bipagem e hairline GOLD de assinatura.
 * Chassi v2: mesmo glass premium do TvStoreCard.
 */

import { Factory } from 'lucide-react';
import type { TvFactoryData, TvFreshness } from '../model/types';
import {
  FACTORY_NO_MOVEMENT_THRESHOLD_HOURS,
  TV_FACTORY_HOURS,
  parseIsoDateLocal,
  toIsoDateLocal,
} from '../model/tvMath';
import { TvSourceChip, TvStateChip, TvStockBadge } from './TvChips';
import {
  formatAgoLabel,
  formatInt,
  formatTimeHHMM,
  formatWeekdayDayMonth,
} from './tvFormat';
import { useCountUp } from './useCountUp';

interface TvFabricaCardProps {
  factory: TvFactoryData;
  freshness: TvFreshness;
  now: Date;
}

/** Borda + glow por estado RAG (mesmo chassi do TvStoreCard). */
const RAG_FRAME: Record<TvFactoryData['rag'], string> = {
  ok: 'border border-[#57715B]/10 shadow-[0_8px_32px_rgba(0,0,0,0.06)]',
  amber: 'border-2 border-amber-400/60 shadow-[0_8px_32px_rgba(245,158,11,0.18)]',
  red: 'border-2 border-red-400/70 shadow-[0_8px_32px_rgba(229,72,77,0.15)]',
};

/** Card da fábrica: nunca tem meta de venda — só produção/expedição/bip. */
export function TvFabricaCard({ factory, freshness, now }: TvFabricaCardProps) {
  const producao = factory.producao;
  const unidadesAnim = Math.round(useCountUp(producao?.totalUnidades ?? 0));

  const todayIso = toIsoDateLocal(now);
  const isToday = producao?.dataReferencia === todayIso;
  const refLabel =
    producao && !isToday
      ? formatWeekdayDayMonth(parseIsoDateLocal(producao.dataReferencia))
      : null;
  const updTime = formatTimeHHMM(freshness.estoque.updatedAt);

  // Última bipagem: âmbar quando acima do threshold dentro da janela de
  // produção — MESMA janela/threshold do RAG da fábrica (TV_FACTORY_HOURS).
  const bip = factory.expedicoes.ultimaBipagem;
  const bipTime = formatTimeHHMM(bip);
  const bipAgo = formatAgoLabel(bip, now);
  const hour = now.getHours();
  const inProductionWindow =
    hour >= TV_FACTORY_HOURS.start && hour < TV_FACTORY_HOURS.end;
  const bipStale =
    inProductionWindow &&
    (bip == null ||
      now.getTime() - new Date(bip).getTime() >
        FACTORY_NO_MOVEMENT_THRESHOLD_HOURS * 3_600_000);
  const bipColor = bipStale ? 'text-amber-600' : 'text-[#2D362E]';

  return (
    <section
      className={`relative overflow-hidden rounded-[2rem] bg-white/60 p-5 backdrop-blur-xl saturate-150 transition-[border-color,box-shadow] [transition-duration:400ms] motion-reduce:transition-none ${RAG_FRAME[factory.rag]}`}
      data-testid="tv-fabrica-card"
      data-rag={factory.rag}
    >
      {/* Gradiente interno sutil (assinatura glass premium) */}
      <div
        className="pointer-events-none absolute inset-0 bg-gradient-to-br from-white/40 via-transparent to-[#C5A065]/5"
        aria-hidden
      />
      {/* Hairline gold de identidade (topo, sob o radius) */}
      <div className="absolute inset-x-0 top-0 h-0.5 bg-[#C5A065]/60" aria-hidden />

      <div className="relative z-10 flex h-full flex-col">
        {/* Header */}
        <div className="flex h-8 items-center justify-between gap-3">
          <h2 className="flex items-center gap-2.5 truncate text-[28px] font-momma font-semibold leading-8 text-[#2D362E]">
            <Factory style={{ width: 26, height: 26 }} className="shrink-0 text-[#C5A065]" aria-hidden />
            {factory.nome}
          </h2>
          <div className="flex shrink-0 items-center gap-2">
            <TvStateChip rag={factory.rag} />
            <TvStockBadge estoque={factory.estoque} />
            <TvSourceChip channel="factory" liveLevel={freshness.estoque.level} />
          </div>
        </div>

        {/* Produção (64px) */}
        <div className="mt-1.5 flex items-end gap-3">
          <span
            className={`font-momma text-[64px] font-bold leading-none tabular-nums ${producao ? 'text-[#2D362E]' : 'text-[#7C887E]'}`}
            data-testid="tv-fabrica-producao"
          >
            {producao ? formatInt(unidadesAnim) : '—'}
          </span>
          {producao && (
            <span className="pb-0.5 font-momma text-[32px] font-normal leading-none text-[#5F6F63]">
              un
            </span>
          )}
        </div>
        <p className="mt-1 text-[20px] font-momma font-medium leading-tight text-[#7C887E]">
          {producao
            ? `produzido ${refLabel ? `em ${refLabel}` : 'hoje'}${updTime ? ` · atualizado ${updTime}` : ''}`
            : 'sem produção registrada'}
        </p>

        {/* Respiro extra intencional — fábrica não tem barra de meta (§5) */}
        <div className="mt-auto grid grid-cols-3 gap-4">
          <div>
            <p className="text-[22px] font-momma font-medium uppercase tracking-wider text-[#5F6F63]">
              EXPEDIÇÕES
            </p>
            <p className="mt-0.5 font-momma text-[32px] font-medium leading-none text-[#2D362E] tabular-nums">
              {formatInt(factory.expedicoes.saidas)}
            </p>
          </div>
          <div>
            <p className="text-[22px] font-momma font-medium uppercase tracking-wider text-[#5F6F63]">
              ITENS PROD.
            </p>
            <p className="mt-0.5 font-momma text-[32px] font-medium leading-none text-[#2D362E] tabular-nums">
              {producao ? formatInt(producao.itens) : '—'}
            </p>
          </div>
          <div>
            <p className="text-[22px] font-momma font-medium uppercase tracking-wider text-[#5F6F63]">
              ÚLT. BIPAGEM
            </p>
            <p
              className={`mt-0.5 font-momma text-[32px] font-medium leading-none tabular-nums ${bipColor}`}
              data-testid="tv-fabrica-bip"
            >
              {bipTime ?? '—'}
            </p>
            {bipAgo && (
              <p className={`mt-0.5 text-[20px] font-momma leading-tight ${bipStale ? 'text-amber-600' : 'text-[#7C887E]'}`}>
                {bipAgo}
              </p>
            )}
          </div>
        </div>
      </div>
    </section>
  );
}

/**
 * @module features/tv-dashboard/ui/TvExceptions
 *
 * Faixa de exceções do Painel TV (1229×248 — design.md §6.1): grid 2×4
 * preenchido coluna-primeiro, máx 7 itens + slot de overflow "+N outros".
 * v2: linhas de vidro neutras — a COR vive só no ícone e no valor da
 * severidade; estado vazio explícito em emerald suave (nunca área em branco).
 */

import { CheckCircle2, OctagonAlert, TriangleAlert } from 'lucide-react';
import type { TvException, TvExceptionsResult } from '../model/types';

/**
 * Separa a linha em texto principal + valor à direita, por tipo de exceção
 * (design.md §6.1 — anatomia da linha).
 */
function splitException(ex: TvException): { text: string; value: string } {
  switch (ex.kind) {
    case 'stock-out':
      return {
        text: `${ex.produtoNome ?? 'Produto'} — ${ex.lojaNome ?? 'Loja'}`,
        value: '0 un',
      };
    case 'stock-low':
      return {
        text: `${ex.produtoNome ?? 'Produto'} — ${ex.lojaNome ?? 'Loja'}`,
        value: `${ex.quantidade ?? 0} · mín ${ex.quantidadeMinima ?? 0}`,
      };
    case 'no-movement': {
      const m = ex.message.match(/há \d+\s?h/);
      return {
        text: `${ex.lojaNome ?? 'Loja'} — sem bipagem`,
        value: m ? m[0] : '',
      };
    }
    case 'stale-data': {
      const m = ex.message.match(/desde \d{2}:\d{2}/);
      return {
        text: `${ex.lojaNome ?? 'Venda live'} — dado atrasado`,
        value: m ? m[0] : '',
      };
    }
  }
}

/** Lista de exceções com estado vazio confirmado explicitamente. */
export function TvExceptions({ exceptions }: { exceptions: TvExceptionsResult }) {
  const { items, overflowCount, totalCount } = exceptions;
  const isEmpty = totalCount === 0;

  return (
    <section
      className="relative h-full overflow-hidden rounded-[2rem] border border-[#57715B]/10 bg-white/60 p-5 shadow-[0_8px_32px_rgba(0,0,0,0.06)] backdrop-blur-xl saturate-150"
      data-testid="tv-exceptions"
    >
      {/* Gradiente interno sutil (assinatura glass premium) */}
      <div
        className="pointer-events-none absolute inset-0 bg-gradient-to-br from-white/40 via-transparent to-[#C5A065]/5"
        aria-hidden
      />

      <div className="relative z-10 flex h-full flex-col">
        <div className="flex h-7 items-center justify-between">
          <h2 className="text-[24px] font-momma font-semibold uppercase tracking-wider text-[#5F6F63]">
            EXCEÇÕES
          </h2>
          {totalCount > 0 && (
            <span className="font-momma text-[24px] font-medium leading-none text-[#7C887E] tabular-nums">
              {totalCount}
            </span>
          )}
        </div>

        {isEmpty ? (
          <div
            className="flex h-full items-center justify-center gap-4"
            data-testid="tv-exceptions-empty"
          >
            <CheckCircle2 style={{ width: 44, height: 44 }} className="text-emerald-500" aria-hidden />
            <p className="text-[28px] font-momma font-medium text-emerald-600">
              Nenhum alerta — tudo dentro do normal
            </p>
          </div>
        ) : (
          <ul className="mt-3 grid flex-1 grid-flow-col grid-cols-2 grid-rows-4 gap-x-6 gap-y-2">
            {items.map((ex) => {
              const { text, value } = splitException(ex);
              const isRed = ex.severity === 'red';
              return (
                <li
                  key={ex.id}
                  className="tv-fade-in flex items-center gap-3 rounded-xl border border-[#57715B]/5 bg-white/50 px-3"
                  data-testid="tv-exception-row"
                  data-severity={ex.severity}
                >
                  {isRed ? (
                    <OctagonAlert
                      style={{ width: 24, height: 24 }}
                      className="shrink-0 text-red-500"
                      aria-hidden
                    />
                  ) : (
                    <TriangleAlert
                      style={{ width: 24, height: 24 }}
                      className="shrink-0 text-amber-500"
                      aria-hidden
                    />
                  )}
                  <span className="min-w-0 flex-1 truncate text-[24px] font-momma font-medium text-[#2D362E]">
                    {text}
                  </span>
                  {value && (
                    <span
                      className={`shrink-0 font-momma text-[24px] font-medium tabular-nums ${
                        isRed ? 'text-red-600' : 'text-amber-600'
                      }`}
                    >
                      {value}
                    </span>
                  )}
                </li>
              );
            })}
            {overflowCount > 0 && (
              <li
                className="flex items-center rounded-xl px-3 text-[22px] font-momma text-[#5F6F63]"
                data-testid="tv-exceptions-overflow"
              >
                + {overflowCount} outros alertas
              </li>
            )}
          </ul>
        )}
      </div>
    </section>
  );
}

/**
 * @module features/tv-dashboard/ui/TvTopProducts
 *
 * Top 5 produtos do dia da rede (603×248 — design.md §6.2): barras
 * horizontais em GRADIENTE SAGE monocromático (rank = comprimento + ordem,
 * não cor), largura proporcional ao 1º colocado, sobre trilha sage suave.
 */

import type { TvTopProduct } from '../model/tvMath';
import { formatInt } from './tvFormat';

/** Coluna direita da faixa inferior: top 5 produtos por unidades vendidas. */
export function TvTopProducts({ products }: { products: TvTopProduct[] }) {
  const max = products.length > 0 ? Math.max(...products.map((p) => p.quantidade)) : 0;

  return (
    <section
      className="relative h-full overflow-hidden rounded-[2rem] border border-[#57715B]/10 bg-white/60 p-5 shadow-[0_8px_32px_rgba(0,0,0,0.06)] backdrop-blur-xl saturate-150"
      data-testid="tv-top-products"
    >
      {/* Gradiente interno sutil (assinatura glass premium) */}
      <div
        className="pointer-events-none absolute inset-0 bg-gradient-to-br from-white/40 via-transparent to-[#C5A065]/5"
        aria-hidden
      />

      <div className="relative z-10 flex h-full flex-col">
        <h2 className="h-7 text-[22px] font-momma font-semibold uppercase tracking-wider text-[#5F6F63]">
          TOP 5 PRODUTOS · HOJE
        </h2>

        {products.length === 0 ? (
          <div className="flex h-full flex-col items-center justify-center gap-2">
            <span className="font-momma text-[32px] font-medium text-[#7C887E]">—</span>
            <p className="text-[22px] font-momma text-[#7C887E]">aguardando vendas do dia</p>
          </div>
        ) : (
          <ul className="mt-2 flex flex-1 flex-col justify-between">
            {products.slice(0, 5).map((p) => (
              <li key={p.nome} className="h-[34px]">
                <div className="flex h-6 items-center justify-between gap-4">
                  <span className="min-w-0 flex-1 truncate text-[22px] font-momma font-medium text-[#5F6F63]">
                    {p.nome}
                  </span>
                  <span className="shrink-0 font-momma text-[24px] font-medium leading-none text-[#2D362E] tabular-nums">
                    {formatInt(p.quantidade)}
                  </span>
                </div>
                <div className="mt-0.5 h-2 w-full rounded-full bg-[#57715B]/10">
                  <div
                    className="h-full rounded-full bg-gradient-to-r from-[#57715B] to-[#4a6250] transition-[width] [transition-duration:600ms] ease-out motion-reduce:transition-none"
                    style={{ width: `${max > 0 ? Math.max(2, (p.quantidade / max) * 100) : 0}%` }}
                    data-testid="tv-top-product-bar"
                  />
                </div>
              </li>
            ))}
          </ul>
        )}
      </div>
    </section>
  );
}

/**
 * @module features/tv-dashboard/ui/TvDashboard.page
 *
 * Página `/tv` — Dashboard de Crise em TV 1920×1080 (design.md §1–§2, §7–§8).
 * Renderiza FORA do DashboardLayout (fullscreen, sem sidebar), em LIGHT
 * hardcoded (independe do toggle de tema): glassmorphism Momma sobre fundo
 * branco com ambiência da marca (awning, folhas, glows), zero scroll.
 */

import { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Leaf, Settings2 } from 'lucide-react';
import { useTvDashboardData } from '../model/useTvDashboardData';
import { useTvRealtime } from '../model/useTvRealtime';
import { TvHero } from './TvHero';
import { TvStoreCard } from './TvStoreCard';
import { TvFabricaCard } from './TvFabricaCard';
import { TvExceptions } from './TvExceptions';
import { TvTopProducts } from './TvTopProducts';
import { useMinuteClock } from '../model/useMinuteClock';
import './tv.css';

/** Tempo que o botão Metas permanece visível após mousemove (§8.4). */
const METAS_BUTTON_VISIBLE_MS = 5_000;

/**
 * Ambiência Momma replicada do `MommaPageLayout` (que não cabe no chassi
 * fullscreen da TV): awning stripe verde no topo, folhas decorativas
 * ESTÁTICAS (sem `animate-pulse` — §8.2 proíbe animação contínua) e
 * ambient glows verde/dourado.
 */
function TvAmbience() {
  return (
    <div className="pointer-events-none absolute inset-0 overflow-hidden" aria-hidden>
      {/* Awning stripe (toldo da marca) */}
      <div className="absolute left-0 right-0 top-0 h-1.5 bg-[repeating-linear-gradient(90deg,#57715B,#57715B_20px,#ffffff_20px,#ffffff_40px)] opacity-80" />
      {/* Folhas decorativas estáticas */}
      <div className="absolute right-[-10%] top-[-5%] h-[300px] w-[300px] opacity-[0.03]">
        <Leaf className="h-full w-full rotate-12 text-[#57715B]" />
      </div>
      <div className="absolute bottom-[-10%] left-[-15%] h-[400px] w-[400px] opacity-[0.03]">
        <Leaf className="h-full w-full -rotate-45 text-[#57715B]" />
      </div>
      {/* Ambient glows */}
      <div className="absolute left-[10%] top-[20%] h-[200px] w-[200px] rounded-full bg-[#57715B]/5 blur-[80px]" />
      <div className="absolute bottom-[30%] right-[10%] h-[250px] w-[250px] rounded-full bg-[#C5A065]/5 blur-[80px]" />
    </div>
  );
}

/** Card-chassi anônimo do estado de erro total (design.md §7). */
function TvErrorCard() {
  return (
    <section className="relative flex flex-col overflow-hidden rounded-[2rem] border border-[#57715B]/10 bg-white/60 p-5 shadow-[0_8px_32px_rgba(0,0,0,0.06)] backdrop-blur-xl saturate-150">
      <div
        className="pointer-events-none absolute inset-0 bg-gradient-to-br from-white/40 via-transparent to-[#C5A065]/5"
        aria-hidden
      />
      <div className="relative z-10 flex h-full flex-col">
        <div className="flex h-8 items-center justify-between">
          <span className="text-[28px] font-momma font-semibold text-[#7C887E]">—</span>
          <span className="inline-flex h-6 items-center rounded-full border border-amber-400/40 bg-amber-50 px-3 text-[20px] font-momma font-medium text-amber-600">
            sem conexão
          </span>
        </div>
        <span className="mt-4 font-momma text-[64px] font-bold leading-none text-[#7C887E]">—</span>
      </div>
    </section>
  );
}

/** Página raiz do painel TV. */
export default function TvDashboardPage() {
  const navigate = useNavigate();
  const data = useTvDashboardData();
  useTvRealtime();
  const now = useMinuteClock();

  // Botão fantasma "Metas": invisível por padrão; mousemove revela por 5s
  // e suspende o cursor-none enquanto visível (design.md §8.4).
  const [controlsVisible, setControlsVisible] = useState(false);
  const hideTimer = useRef<number | null>(null);
  useEffect(() => {
    const onMove = () => {
      setControlsVisible(true);
      if (hideTimer.current != null) window.clearTimeout(hideTimer.current);
      hideTimer.current = window.setTimeout(
        () => setControlsVisible(false),
        METAS_BUTTON_VISIBLE_MS,
      );
    };
    window.addEventListener('mousemove', onMove);
    return () => {
      window.removeEventListener('mousemove', onMove);
      if (hideTimer.current != null) window.clearTimeout(hideTimer.current);
    };
  }, []);

  // ── Loading inicial (§7): wordmark + frase + 3 pontos em sequência ──
  if (data.isLoading) {
    return (
      <div className="fixed inset-0 flex select-none flex-col items-center justify-center gap-5 overflow-hidden bg-white font-momma antialiased">
        <TvAmbience />
        <span className="relative text-[40px] font-bold uppercase tracking-[0.3em] text-[#C5A065]">
          MOMMA
        </span>
        <span className="relative text-[24px] text-[#5F6F63]">carregando painel…</span>
        <div className="relative flex gap-2 text-[24px] text-[#7C887E]" aria-hidden>
          <span className="tv-dot">·</span>
          <span className="tv-dot">·</span>
          <span className="tv-dot">·</span>
        </div>
      </div>
    );
  }

  const storeCards = data.stores.slice(0, data.factory ? 5 : 6);

  return (
    <div
      className={`fixed inset-0 select-none overflow-hidden bg-white font-momma text-[#2D362E] antialiased ${
        controlsVisible ? '' : 'cursor-none'
      }`}
      data-testid="tv-dashboard"
    >
      <TvAmbience />

      <div className="tv-pixel-shift relative h-full">
        <div className="tv-content-enter grid h-full grid-rows-[152px_1fr_248px] gap-6 px-8 py-6">
          {/* Linha 1 — hero */}
          <TvHero network={data.network} freshness={data.freshness} now={now} />

          {/* Linha 2 — grid 3×2 de unidades (fábrica na posição 6) */}
          <div className="grid grid-cols-3 grid-rows-2 gap-6">
            {data.isError ? (
              <>
                {Array.from({ length: 6 }, (_, i) => (
                  <TvErrorCard key={i} />
                ))}
              </>
            ) : (
              <>
                {storeCards.map((store) => (
                  <TvStoreCard
                    key={store.lojaId}
                    store={store}
                    liveLevel={data.freshness.vendasLive.level}
                    now={now}
                  />
                ))}
                {data.factory && (
                  <TvFabricaCard
                    factory={data.factory}
                    freshness={data.freshness}
                    now={now}
                  />
                )}
              </>
            )}
          </div>

          {/* Linha 3 — exceções (2fr) + top 5 produtos (1fr) */}
          <div className="grid grid-cols-[2fr_1fr] gap-6">
            <TvExceptions exceptions={data.exceptions} />
            <TvTopProducts products={data.topProducts} />
          </div>
        </div>
      </div>

      {/* Botão fantasma de Metas (§8.4) */}
      <button
        type="button"
        onClick={() => navigate('/tv/metas')}
        data-mia-action="abrir-metas-painel-tv"
        className={`fixed bottom-6 right-8 flex h-11 items-center gap-2 rounded-full border border-[#57715B]/15 bg-white/80 px-5 text-[20px] font-momma font-medium text-[#57715B] shadow-[0_4px_16px_rgba(0,0,0,0.08)] backdrop-blur-md transition-opacity duration-200 motion-reduce:transition-none ${
          controlsVisible ? 'opacity-100' : 'pointer-events-none opacity-0'
        }`}
        aria-hidden={!controlsVisible}
        tabIndex={controlsVisible ? 0 : -1}
      >
        <Settings2 style={{ width: 22, height: 22 }} aria-hidden />
        Metas
      </button>
    </div>
  );
}

